        public static bool Has(string key) => T.ContainsKey(key);

        public static string Get(string key, params object[] args)
        {
            if (!T.TryGetValue(key, out var v)) return key;
            var s = v[Index];
            return args.Length == 0 ? s : string.Format(s, args);
        }

        /// <summary>Назва застосунку браслета (для «Дія при натисканні»)</summary>
        public static string App(string key) => Has("app_" + key) ? Get("app_" + key) : key;
    }
}
